"""Public entry-level pay data (config/pay/entry-pay.csv): an estimate for roles that don't state pay."""

from __future__ import annotations

import csv
import re
from functools import lru_cache
from statistics import median
from pathlib import Path

from .dedupe import company_key

DEFAULT = Path(__file__).resolve().parent.parent / "config" / "pay" / "entry-pay.csv"
# Generated by `careeros payers` from real offers; the curated file wins for a company in both.
OFFERS = DEFAULT.parent / "offers-pay.csv"
OFFERS_URL = "https://raw.githubusercontent.com/kuutsav/leetcode-compensation/master/data/final_data.json"
SOURCES = {
    "lcc": ("LeetCode offer posts via leetcode-compensation", "https://0xku.github.io/leetcode-compensation/"),
    "250cl": ("250CompanyList", "https://github.com/KushalVijay/250CompanyList"),
    "jobrise": ("Jobrise 2026", "https://jobrise.io/en/blog/top-paying-companies-india-2026/"),
}


@lru_cache(maxsize=4)
def load(path: str | None = None) -> dict[str, dict]:
    if path:
        return _load_one(Path(path))
    out = _load_one(OFFERS)
    out.update(_load_one(DEFAULT))  # curated rows win
    return out


def _load_one(p: Path) -> dict[str, dict]:
    out: dict[str, dict] = {}
    if not p.exists():
        return out
    with p.open(encoding="utf-8", newline="") as f:
        for r in csv.DictReader(f):
            try:
                band = {"low": float(r["low_lpa"]), "high": float(r["high_lpa"]), "basis": r.get("basis", ""),
                        "source": " · ".join(SOURCES.get(s, (s, ""))[0] for s in (r.get("sources") or "").split(";") if s),
                        "url": next((SOURCES[s][1] for s in (r.get("sources") or "").split(";") if s in SOURCES), "")}
            except (KeyError, ValueError):
                continue
            for name in [r["company"]] + [a for a in (r.get("aliases") or "").split(";") if a.strip()]:
                k = company_key(name)
                if k:
                    out[k] = band
    return out


def band(company: str, path: str | None = None) -> dict | None:
    """{low, high, basis, source, url} for this company, or None."""
    return load(path).get(company_key(company or ""))


def describe(b: dict) -> str:
    lo, hi = b["low"], b["high"]
    rng = f"{lo:g}" if lo == hi else f"{lo:g}–{hi:g}"
    return f"{rng} LPA for freshers ({b['basis']}, {b['source']})"


# ------------------------------------------------------------------ offers -> bands

_GENERIC = re.compile(r"^(mnc|startup|product based|service based|confidential|undisclosed|unknown|na|n/a|fintech|"
                      r"big tech|faang|maang|tier ?\d|stealth|series [a-e].*|.*startup)$", re.I)


def _num(x):
    try:
        return float(x)
    except (TypeError, ValueError):
        return None


def offer_bands(records: list[dict], max_yoe: float = 1.5, since: str = "2024-01-01", min_n: int = 2) -> list[dict]:
    """Per company, the median base and total of real early-career offers (LPA)."""
    by: dict[str, list[tuple[float, float]]] = {}
    names: dict[str, str] = {}
    for r in records:
        yoe, base, total = _num(r.get("yoe")), _num(r.get("base")), _num(r.get("total"))
        name = str(r.get("company") or "").strip()
        if yoe is None or yoe > max_yoe or not base or base <= 0 or base > 200 or str(r.get("date", "")) < since:
            continue
        if not name or _GENERIC.match(name):
            continue
        k = company_key(name)
        if not k:
            continue
        by.setdefault(k, []).append((base, total if total and total >= base else base))
        names.setdefault(k, name)
    rows = []
    for k, offers in by.items():
        if len(offers) < min_n:
            continue
        rows.append({"company": names[k], "low_lpa": round(median(b for b, _ in offers), 1),
                     "high_lpa": round(median(t for _, t in offers), 1), "n": len(offers)})
    return sorted(rows, key=lambda r: -r["low_lpa"])


def write_offers(rows: list[dict], path: Path = OFFERS) -> None:
    with Path(path).open("w", encoding="utf-8", newline="") as f:
        w = csv.writer(f)
        w.writerow(["company", "aliases", "low_lpa", "high_lpa", "basis", "sources"])
        for r in rows:
            w.writerow([r["company"], "", r["low_lpa"], r["high_lpa"], f"median base and total of {r['n']} offers, up to 1.5 years", "lcc"])
    load.cache_clear()
